    try:
        # Fano incidence adjacency: vertices 0..6 = points, 7..13 = lines;
        # point i lies on lines {i, i-1, i-3} mod 7.
        adj = np.zeros((n, n), dtype=bool)
        for i in range(7):
            for j in (i, (i - 1) % 7, (i - 3) % 7):
                adj[i, 7 + j] = True
                adj[7 + j, i] = True
        # Graph distances via BFS (Heawood diameter 3).
        gdist = np.full((n, n), 10, dtype=int)
        for s in range(n):
