                frontier = nxt
        wiu = np.triu_indices(n, 1)
        wv = np.where(adj[wiu], 50.0, 1.0)

        def make_stress(tv):
            def stress(x):
                Q = x.reshape(n, d)
                D2 = ((Q[:, None, :] - Q[None, :, :]) ** 2).sum(-1)
                r_ = D2[wiu] - tv
                return (wv * r_ * r_).sum()

            def sgrad(x):
                Q = x.reshape(n, d)
                diff = Q[:, None, :] - Q[None, :, :]
                D2 = (diff ** 2).sum(-1)
                coef = 4.0 * np.where(adj, 50.0, 1.0) * (D2 - tv)
                np.fill_diagonal(coef, 0.0)
                return (coef[:, :, None] * diff).sum(1).ravel()
            return stress, sgrad

        schedules = [(1.0, 1.6, 2.4, 3.2),
